        amount = bound(amount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= amount);
        vm.assume(amount >= minSum);
        try c.SetMinSum(minSum) {} catch { return; }
        try c.SetLogFile(address(new LogFile())) {} catch { return; }
        try c.Initialized() {} catch { return; }
        try c.Deposit{value: amount}() {} catch { return; }
        bool reverted;
        try c.Collect(amount) { reverted = false; } catch { reverted = true; }
        assertTrue(!reverted);
    }

    function testFuzz_run(uint256 minSum, uint256 amount) public {
        _run(minSum, amount);
    }

    receive() external payable {}
